import java.sql.*;
import java.util.logging.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_SORT_PATTERN = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String department = req.getParameter("dept");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        // Validate sort column against allowlist pattern
        if (sortCol != null && !SAFE_SORT_PATTERN.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }
        if (sortCol == null) sortCol = "created_at";

        // Sanitize department - escape HTML entities for XSS prevention
        String safeDept = StringEscapeUtils.escapeHtml4(department);

        // Build the report query
        StringBuilder query = new StringBuilder();
        query.append("SELECT r.id, r.title, r.created_at, r.author, r.status ");
        query.append("FROM reports r WHERE r.department = ? ");
        query.append("AND r.created_at BETWEEN ? AND ? ");

        // Dynamic filter - allows power users to add custom WHERE clauses
        // Note: this is restricted to read-only database users in production
        if (filterExpr != null && !filterExpr.isEmpty()) {
            // Basic blocklist check
            String upper = filterExpr.toUpperCase();
            if (upper.contains("DROP") || upper.contains("DELETE") || 
                upper.contains("INSERT") || upper.contains("UPDATE") ||
                upper.contains("ALTER") || upper.contains("EXEC")) {
                resp.sendError(400, "Forbidden keyword in filter");
                return;
            }
            query.append("AND (").append(filterExpr).append(") ");
        }

        query.append("ORDER BY ").append(sortCol).append(" DESC ");
        query.append("LIMIT 100");

        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();
            stmt = conn.prepareStatement(query.toString());
            stmt.setString(1, department);
            stmt.setString(2, dateFrom);
            stmt.setString(3, dateTo);

            rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"created_at\": \"%s\", \"author\": \"%s\", \"status\": \"%s\"}",
                    rs.getInt("id"),
                    StringEscapeUtils.escapeJson(rs.getString("title")),
                    rs.getString("created_at"),
                    StringEscapeUtils.escapeJson(rs.getString("author")),
                    rs.getString("status"));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        // Connection pool managed by container (JNDI)
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
            return ds.getConnection();
        } catch (javax.naming.NamingException e) {
            throw new SQLException("JNDI lookup failed", e);
        }
    }

    private void closeQuietly(ResultSet rs, PreparedStatement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (SQLException ignored) {}
        try { if (stmt != null) stmt.close(); } catch (SQLException ignored) {}
        try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
    }
}
